import{_ as t,o,c as a,a2 as r}from"./chunks/framework.G0y0PQA7.js";const n="/relio/shots/en/import-text-preview.png",u=JSON.parse('{"title":"Import and other formats","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/import.md","filePath":"en/features/import.md"}'),i={name:"en/features/import.md"};function d(s,e,l,m,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="import-and-other-formats" tabindex="-1">Import and other formats <a class="header-anchor" href="#import-and-other-formats" aria-label="Permalink to &quot;Import and other formats&quot;">​</a></h1><p>How to import a model from SQL (<code>CREATE TABLE</code>), DBML, Mermaid or Markdown, and how to import objects from another <code>.erm</code> file. Importing by connecting to a database is covered in <a href="/relio/en/features/database">Databases</a>.</p><h2 id="import-menu" tabindex="-1">Import menu <a class="header-anchor" href="#import-menu" aria-label="Permalink to &quot;Import menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu › Item</th><th>What it does</th></tr></thead><tbody><tr><td>File › Import › From DB…</td><td>Connects to a database and imports its structure. <a href="/relio/en/features/database#import-from-db">Databases</a></td></tr><tr><td>File › Import › From file…</td><td>Picks objects from another <code>.erm</code> file and adds them.</td></tr><tr><td>File › Import › From SQL, DBML, Mermaid or Markdown…</td><td>Builds a model from a text file or pasted text. Works without an open document.</td></tr></tbody></table><p>Dragging an <code>.sql</code>, <code>.ddl</code>, <code>.dbml</code>, <code>.mmd</code>, <code>.mermaid</code> or <code>.md</code> file onto the window, or opening one with File › Open…, also opens this import dialog (nothing is added right away).</p><h2 id="importing-from-sql-dbml-mermaid-or-markdown" tabindex="-1">Importing from SQL, DBML, Mermaid or Markdown <a class="header-anchor" href="#importing-from-sql-dbml-mermaid-or-markdown" aria-label="Permalink to &quot;Importing from SQL, DBML, Mermaid or Markdown&quot;">​</a></h2><h3 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Input</td><td><strong>File</strong> or <strong>Paste</strong>. Files up to 32 MB, pasted text up to 8 MB.</td></tr><tr><td>File path</td><td><code>.sql</code> · <code>.ddl</code> · <code>.dbml</code> · <code>.mmd</code> · <code>.mermaid</code> · <code>.md</code>. Pick it with <strong>Browse…</strong>.</td></tr><tr><td>Encoding</td><td><strong>Auto-detect (BOM, UTF-8)</strong> by default. For a file that is not UTF-8 and has no BOM, you are asked to choose the encoding (it is never guessed).</td></tr><tr><td>Format</td><td>Auto-detect · SQL · DBML · Mermaid · Markdown</td></tr><tr><td>Dialect</td><td>For SQL — Auto-detect · PostgreSQL · MySQL/MariaDB · Oracle · SQL Server · Standard SQL</td></tr></tbody></table><p>Files with <code>CREATE TABLE</code> statements, such as <code>pg_dump</code>, <code>mysqldump</code>, SSMS scripts or Oracle DDL, are read as they are. Statements that cannot be read are skipped with a warning.</p><h3 id="destination-and-options" tabindex="-1">Destination and options <a class="header-anchor" href="#destination-and-options" aria-label="Permalink to &quot;Destination and options&quot;">​</a></h3><ul><li><strong>Import into</strong> — <strong>New document</strong> (a new untitled tab) or <strong>Merge into the current document</strong>. If no document is open or it is read-only, only New document is available.</li><li>The new document uses the database the format specifies. If the format does not specify one, the database you chose is used (or, if the SQL dialect is known, that database).</li><li><strong>Read comments as</strong> — Where comments go: <strong>Automatic (logical name : description)</strong> · <strong>Description only</strong> · <strong>Logical name only</strong>.</li><li><strong>Convert unquoted names to the database&#39;s default case</strong> — When on, unquoted names are converted to upper or lower case following that database&#39;s rules.</li></ul><h3 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;Preview&quot;">​</a></h3><p>Click <strong>Preview</strong> to see, before anything is added, how many tables, columns, relationships and indexes were found, along with warnings and info. For large files, &quot;Reading… n s&quot; is shown; <strong>Cancel</strong> stops without changing anything. <strong>Back</strong> returns to the input.</p><figure class="shot" data-scene="import-text-preview"><img src="'+n+'" alt="Import preview — the numbers of tables, columns and relationships found, and warnings" loading="lazy"><figcaption>Import preview — the numbers of tables, columns and relationships found, and warnings</figcaption></figure><h3 id="when-names-clash" tabindex="-1">When names clash <a class="header-anchor" href="#when-names-clash" aria-label="Permalink to &quot;When names clash&quot;">​</a></h3><p>When merging into the current document and objects with the same name exist, you choose how to handle them after clicking <strong>Import</strong>.</p><table tabindex="0"><thead><tr><th>Action</th><th>What it does</th></tr></thead><tbody><tr><td>Overwrite</td><td>Replaces the contents only; position, color and categories stay as they are.</td></tr><tr><td>Skip</td><td>Does not import that object.</td></tr><tr><td>Add with a new name</td><td>Adds it under a different name.</td></tr></tbody></table><p>Decide for all at once with <strong>Apply to all remaining</strong>, or per object with &quot;(choose one by one)&quot;. The whole merge is undone with a single undo (<kbd>Ctrl</kbd>+<kbd>Z</kbd>).</p><h3 id="result" tabindex="-1">Result <a class="header-anchor" href="#result" aria-label="Permalink to &quot;Result&quot;">​</a></h3><p>After importing, the <strong>Import result</strong> (or <strong>Merge result</strong>) window shows how many objects were created (merged) and lists the warnings by Line:col · Kind · Details · Skipped text. <strong>Copy list</strong> copies them, and the same warnings are kept in the problem list.</p><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>You can import SQL made by another tool, refine it in Relio, and <a href="/relio/en/features/export#text-formats-dbml-mermaid-markdown-model-json">export</a> it again as DBML or Mermaid. With the command-line <code>relio import</code>, you can create an <code>.erm</code> without opening the app. <a href="/relio/en/features/cli#relio-import">Command line</a></p></div><h2 id="importing-from-another-erm-file" tabindex="-1">Importing from another .erm file <a class="header-anchor" href="#importing-from-another-erm-file" aria-label="Permalink to &quot;Importing from another .erm file&quot;">​</a></h2><p>Choose File › Import › From file… and pick an <code>.erm</code> file to see the <strong>Objects to import (this file&#39;s DB: …)</strong> list. Tables, views, notes, column groups, sequences, triggers and tablespaces are grouped by kind, and the checked ones are added to the current document (kinds the file does not have are not shown, and images cannot be selected). Everything is checked at first; with <strong>Merge words</strong> at the bottom turned on, words with identical contents are merged into one.</p><ul><li>For objects with the same name, choose Overwrite · Skip · Add with a new name as above.</li><li>A category whose name matches an existing one (ignoring leading and trailing spaces and case) is not created again; its members are just added to that category.</li><li>The whole import is one undo step.</li></ul>',24)])])}const g=t(i,[["render",d]]);export{u as __pageData,g as default};
